                    Description = "Package picked up",
                    Location = "Los Angeles, CA"
                },
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 6, 24, 14, 30, 0, TimeSpan.Zero),
                    Description = "Arrived at sorting facility",
                    Location = "Phoenix, AZ"
                },
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 6, 25, 8, 15, 0, TimeSpan.Zero),
                    Description = "Departed facility",
                    Location = "Memphis, TN"
                }
            ]
        },
        ["TRK-2002"] = new Shipment
        {
            TrackingNumber = "TRK-2002",
            Status = "Delivered",
            Location = "Seattle, WA",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 25, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 6, 22, 10, 0, 0, TimeSpan.Zero),
                    Description = "Package picked up",
                    Location = "Portland, OR"
                },
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 6, 23, 16, 0, 0, TimeSpan.Zero),
                    Description = "In transit",
