                },
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 6, 24, 11, 0, 0, TimeSpan.Zero),
                    Description = "Out for delivery",
                    Location = "Seattle, WA"
                },
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 6, 24, 14, 22, 0, TimeSpan.Zero),
                    Description = "Delivered — signed by J. Smith",
                    Location = "Seattle, WA"
                }
            ]
        },
        ["TRK-3003"] = new Shipment
        {
            TrackingNumber = "TRK-3003",
            Status = "Processing",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 3, 18, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 6, 25, 20, 0, 0, TimeSpan.Zero),
                    Description = "Label created",
                    Location = "Chicago, IL"
                }
